const envelope = $input.first().json ?? {};
const body = envelope.body ?? envelope;
const update = Array.isArray(body.updates)
  ? (body.updates[0] ?? {})
  : (body.update ?? body);

const eventType = String(update.update_type ?? '');
if (!['bot_started', 'message_created', 'message_callback'].includes(eventType)) {
  return [];
}

const message = update.message ?? {};
const messageBody = message.body ?? {};
const callback = update.callback ?? {};
const callbackUser = callback.user ?? {};
const sender = message.sender ?? {};
const updateUser = update.user ?? {};
const user = eventType === 'message_callback'
  ? (callbackUser.user_id ? callbackUser : (updateUser.user_id ? updateUser : sender))
  : (sender.user_id ? sender : updateUser);

const userIdValue = user.user_id ?? update.user_id;
if (userIdValue === undefined || userIdValue === null || String(userIdValue) === '') {
  return [];
}

const userId = String(userIdValue);
const chatId = String(
  update.chat_id ??
  message.recipient?.chat_id ??
  callback.chat_id ??
  userId
);
const callbackPayload = eventType === 'message_callback'
  ? String(callback.payload ?? '')
  : '';
const text = String(messageBody.text ?? '');
const attachments = Array.isArray(messageBody.attachments)
  ? messageBody.attachments
  : [];
const contact = attachments.find((attachment) => attachment?.type === 'contact');
const contactPayload = contact?.payload ?? {};
const vcfInfo = String(contactPayload.vcf_info ?? contactPayload.vcfInfo ?? '');
const hash = String(contactPayload.hash ?? '');
const maxInfo = contactPayload.max_info ?? contactPayload.maxInfo ?? {};

const phoneMatch = vcfInfo.match(/(?:^|\r?\n)TEL(?:;[^:\r\n]*)?:([^\r\n]+)/i);
const phoneDigits = String(phoneMatch?.[1] ?? '').replace(/\D/g, '');
let phone = '';
if (phoneDigits.length >= 10 && phoneDigits.length <= 15) {
  if (phoneDigits.length === 11 && phoneDigits.startsWith('8')) {
    phone = '+7' + phoneDigits.slice(1);
  } else {
    phone = '+' + phoneDigits;
  }
}

const maxInfoId = maxInfo.user_id ?? maxInfo.userId;
const contactReceived = Boolean(
  contact &&
  hash &&
  vcfInfo &&
  phone &&
  (maxInfoId === undefined || String(maxInfoId) === userId)
);

const firstName = String(user.first_name ?? maxInfo.first_name ?? '').trim();
const lastName = String(user.last_name ?? maxInfo.last_name ?? '').trim();
const vcfNameMatch = vcfInfo.match(/(?:^|\r?\n)FN(?:;[^:\r\n]*)?:([^\r\n]+)/i);
const name = (
  [firstName, lastName].filter(Boolean).join(' ') ||
  String(user.name ?? maxInfo.name ?? vcfNameMatch?.[1] ?? '')
).trim();
const username = String(user.username ?? maxInfo.username ?? '').trim();
const messageId = messageBody.mid ?? message.mid ?? update.message_id;
const eventId = String(
  update.update_id ??
  update.event_id ??
  callback.callback_id ??
  messageId ??
  [eventType, update.timestamp ?? '', userId, chatId, callbackPayload, text].join(':')
);

return [{
  json: {
    event_type: eventType,
    event_id: eventId,
    user_id: userId,
    chat_id: chatId,
    callback_payload: callbackPayload,
    text,
    name,
    phone,
    username,
    contact_received: contactReceived,
    received_at: new Date().toISOString()
  }
}];

const event = $items('Нормализация события')[0].json;
const prior = $input.first().json ?? {};
if (prior.last_event_id && String(prior.last_event_id) === String(event.event_id)) return [];

const now = new Date();
const isoNow = now.toISOString();
const localTime = new Intl.DateTimeFormat('ru-RU', {
  timeZone: 'Asia/Yekaterinburg',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit'
}).format(now);

const callbackButton = (text, payload) => ({ type: 'callback', text, payload });
const keyboard = (buttons) => [{
  type: 'inline_keyboard',
  payload: { buttons }
}];
const servicesKeyboard = keyboard([
  [callbackButton('🍽 Кухонные фасады', 'service_kitchen')],
  [callbackButton('🚪 Двери для шкафов-купе', 'service_wardrobe_doors')],
  [callbackButton('👔 Фасады для гардеробных', 'service_dressing')],
  [callbackButton('🧩 Другие мебельные фасады', 'service_other')]
]);
const methodKeyboard = keyboard([
  [callbackButton('📲 Жду звонка', 'method_callback')],
  [callbackButton('☎️ Связаться самостоятельно', 'method_self')]
]);
const contactKeyboard = keyboard([
  [{ type: 'request_contact', text: '📱 Передать контакт MAX' }]
]);
const newRequestKeyboard = keyboard([
  [callbackButton('🔄 Оставить новую заявку', 'new_request')]
]);

const welcomeText = 'Здравствуйте! 👋\n\nИзготавливаем мебельные фасады на заказ из МДФ и ЛДСП — любой сложности, под ваши размеры и интерьер.\n\nСовременное производство, индивидуальный подход и гарантия 1 год. Менеджер поможет подобрать решение и рассчитает стоимость.';
const methodText = 'Менеджер Наталья может позвонить вам с 09:00 до 18:00. Или вы можете связаться с ней самостоятельно.';
const contactText = 'Чтобы менеджер Наталья могла вам позвонить, передайте свой контакт MAX 👇';
const adText = '──────────\n\n🤖 Этот бот создал Pulat Safarov\n\nСоздаю ботов и сайты. Автоматизирую любые рутинные задачи.\n\n📞 REPLACE_WITH_DEVELOPER_PHONE';
const serviceNames = {
  service_kitchen: 'Кухонные фасады',
  service_wardrobe_doors: 'Двери для шкафов-купе',
  service_dressing: 'Фасады для гардеробных',
  service_other: 'Другие мебельные фасады'
};

let session = {
  user_id: String(prior.user_id ?? event.user_id),
  chat_id: String(event.chat_id ?? prior.chat_id ?? event.user_id),
  stage: String(prior.stage ?? 'new'),
  service: String(prior.service ?? ''),
  connection_method: String(prior.connection_method ?? ''),
  name: String(prior.name ?? event.name ?? ''),
  phone: String(prior.phone ?? ''),
  username: String(prior.username ?? event.username ?? ''),
  last_event_id: String(event.event_id),
  application_id: String(prior.application_id ?? ''),
  manager_notified: String(prior.manager_notified ?? 'false'),
  updated_at: isoNow
};

let clientOutgoing;
let managerOutgoing = null;
let isLead = false;
let status = 'dialog';

const resendCurrentStep = () => {
  if (session.stage === 'await_service') {
    return { text: 'Пожалуйста, выберите услугу кнопкой ниже 👇', attachments: servicesKeyboard };
  }
  if (session.stage === 'await_connection_method') {
    return { text: methodText, attachments: methodKeyboard };
  }
  if (session.stage === 'await_contact') {
    return { text: contactText, attachments: contactKeyboard };
  }
  if (session.stage === 'completed') {
    return {
      text: 'Ваша заявка уже оформлена ✅\n\nЕсли хотите оставить ещё одну, нажмите кнопку ниже.',
      attachments: newRequestKeyboard
    };
  }
  return { text: welcomeText, attachments: servicesKeyboard };
};

const startAgain = !prior.user_id || event.event_type === 'bot_started' || event.callback_payload === 'new_request';
if (startAgain) {
  session = {
    ...session,
    stage: 'await_service',
    service: '',
    connection_method: '',
    name: String(event.name ?? prior.name ?? ''),
    phone: '',
    application_id: '',
    manager_notified: 'false'
  };
  clientOutgoing = { text: welcomeText, attachments: servicesKeyboard };
} else if (session.stage === 'await_service' && serviceNames[event.callback_payload]) {
  session.service = serviceNames[event.callback_payload];
  session.stage = 'await_connection_method';
  clientOutgoing = { text: methodText, attachments: methodKeyboard };
} else if (session.stage === 'await_connection_method' && event.callback_payload === 'method_callback') {
  session.connection_method = 'Ждёт звонка';
  session.stage = 'await_contact';
  clientOutgoing = { text: contactText, attachments: contactKeyboard };
} else if (session.stage === 'await_connection_method' && event.callback_payload === 'method_self') {
  session.connection_method = 'Свяжется самостоятельно';
  session.application_id = 'max-' + session.user_id + '-' + String(event.event_id).replace(/[^a-zA-Z0-9_-]/g, '-');
  session.name = session.name || event.name || 'не указано';
  isLead = true;
  status = 'new';
  const usernameLine = session.username ? '\nUsername: @' + session.username : '';
  managerOutgoing = {
    text: '🔔 Клиент решил связаться самостоятельно\n\nУслуга: ' + session.service +
      '\nКлиент в MAX: ' + session.name + usernameLine +
      '\nMAX ID: ' + session.user_id +
      '\nЧат ID: ' + session.chat_id +
      '\n\nТелефон клиента не запрашивался.' +
      '\nЗаявка получена: ' + localTime
  };
  clientOutgoing = {
    text: 'Свяжитесь с менеджером Натальей самостоятельно:\n\n📞 REPLACE_WITH_MANAGER_PHONE\n\nРабочее время: с 09:00 до 18:00.\n\n' + adText,
    format: 'markdown',
    attachments: newRequestKeyboard
  };
} else if (session.stage === 'await_contact' && event.contact_received && event.phone) {
  session.connection_method = 'Ждёт звонка';
  session.name = event.name || session.name || 'не указано';
  session.phone = event.phone;
  session.username = event.username || session.username;
  session.application_id = 'max-' + session.user_id + '-' + String(event.event_id).replace(/[^a-zA-Z0-9_-]/g, '-');
  isLead = true;
  status = 'new';
  const usernameLine = session.username ? '\nUsername: @' + session.username : '';
  managerOutgoing = {
    text: '🔔 Новая заявка\n\nУслуга: ' + session.service +
      '\nКлиент: ' + session.name +
      '\nТелефон: ' + session.phone + usernameLine +
      '\nMAX ID: ' + session.user_id +
      '\nЧат ID: ' + session.chat_id +
      '\n\nСтатус: ждёт звонка с 09:00 до 18:00' +
      '\nЗаявка получена: ' + localTime
  };
  clientOutgoing = {
    text: 'Спасибо, ' + session.name + '! Ваш контакт получен ✅\n\nМенеджер Наталья свяжется с вами с 09:00 до 18:00.\n\n' + adText,
    format: 'markdown',
    attachments: newRequestKeyboard
  };
} else {
  clientOutgoing = resendCurrentStep();
}

return [{
  json: {
    ...session,
    is_lead: isLead,
    created_at: isoNow,
    status,
    client_outgoing: clientOutgoing,
    manager_outgoing: managerOutgoing
  }
}];

const source = $items('Сценарий бота')[0].json;
return [{
  json: {
    ...source,
    stage: 'completed',
    manager_notified: 'true',
    updated_at: new Date().toISOString(),
    status: 'new'
  }
}];

const source = $input.first().json;
return [{
  json: {
    user_id: String(source.user_id ?? ''),
    chat_id: String(source.chat_id ?? ''),
    stage: String(source.stage ?? ''),
    service: String(source.service ?? ''),
    connection_method: String(source.connection_method ?? ''),
    name: String(source.name ?? ''),
    phone: String(source.phone ?? ''),
    username: String(source.username ?? ''),
    last_event_id: String(source.last_event_id ?? ''),
    application_id: String(source.application_id ?? ''),
    manager_notified: String(source.manager_notified ?? 'false'),
    updated_at: String(source.updated_at ?? new Date().toISOString())
  }
}];

const source = $items('Завершить заявку')[0].json;
return [{
  json: {
    application_id: String(source.application_id ?? ''),
    created_at: String(source.created_at ?? new Date().toISOString()),
    service: String(source.service ?? ''),
    connection_method: String(source.connection_method ?? ''),
    name: String(source.name ?? ''),
    phone: String(source.phone ?? ''),
    username: String(source.username ?? ''),
    user_id: String(source.user_id ?? ''),
    chat_id: String(source.chat_id ?? ''),
    manager_notified: 'true',
    status: String(source.status ?? 'new')
  }
}];
